package io.github.gfander.dualforge;
import java.nio.file.*;import java.util.*;import java.util.function.Consumer;import java.util.zip.*;
import cpw.mods.jarhandling.JarContents;import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.loading.*;import net.neoforged.fml.loading.moddiscovery.ModFile;import net.neoforged.neoforgespi.locating.ModFileDiscoveryAttributes;
import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.util.*;
public final class TypedRegistryContract {
 static final String E="demo/shelves/EntryPoint",I="demo/shelves/Items",T="demo/shelves/Shelves",C="demo/shelves/Consumer",F=ForgeRegistryTransformationPlan.F,H=ForgeRegistryTransformationPlan.H;static Path original,out;static PinnedHostOracle oracle;static String metadata;static int negatives,assertions;
 static ClassNode read(byte[] b){return ForgeRegistryTransformationPlan.read(b);}static byte[] bytes(ClassNode n){return ForgeRegistryTransformationPlan.bytes(n);}static MethodNode method(ClassNode n,String name){return n.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}
 static Map<String,ClassNode> nodes()throws Exception {Map<String,ClassNode> n=new TreeMap<>();try(ZipFile z=new ZipFile(original.toFile())){for(var e:z.stream().toList())if(e.getName().endsWith(".class")){var c=read(z.getInputStream(e).readAllBytes());n.put(c.name,c);}}return n;}
 static ForgeRegistryTransformationPlan plan(Path jar)throws Exception {var file=(ModFile)new ForgeModReader().read(JarContents.of(jar),ModFileDiscoveryAttributes.DEFAULT);file.setScanResult(file.compileContent(),null);LoadingModList.of(List.of(),List.of(file),List.of(),List.of(),Map.of());return ForgeRegistryTransformationPlan.create(file.getModInfos().getFirst(),E,oracle);}
 static String text(MethodNode m){Textifier t=new Textifier();m.accept(new TraceMethodVisitor(t));return t.text.toString();}
 static void check(boolean b,String label){if(!b)throw new AssertionError(label);assertions++;System.out.println("PASS "+label);}
 static InvokeDynamicInsnNode indy(ClassNode n,String name){return Arrays.stream(method(n,name).instructions.toArray()).filter(x->x instanceof InvokeDynamicInsnNode).map(x->(InvokeDynamicInsnNode)x).findFirst().orElseThrow();}
 static void reject(String label,String owner,Consumer<ClassNode> change,String reason)throws Exception {
  Map<String,ClassNode> ns=nodes();change.accept(ns.get(owner));Path jar=out.resolve(label+".jar");try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(jar))){z.putNextEntry(new ZipEntry("META-INF/mods.toml"));z.write(metadata.getBytes(java.nio.charset.StandardCharsets.UTF_8));z.closeEntry();for(var n:ns.values()){z.putNextEntry(new ZipEntry(n.name+".class"));z.write(bytes(n));z.closeEntry();}}
  byte[] before=Files.readAllBytes(jar);try{plan(jar);throw new AssertionError("Accepted "+label);}catch(IllegalStateException e){if(!e.getMessage().contains(reason))throw new AssertionError(label+" unexpected "+e,e);}
  check(Arrays.equals(before,Files.readAllBytes(jar)),label+" original unchanged");negatives++;System.out.println("REJECT "+label+" stage=complete-plan reason="+reason+" outputTargets=none originalUnchanged=true");
 }
 public static void main(String[] args)throws Exception {
  original=Path.of(args[0]);oracle=new PinnedHostOracle(Path.of(args[1]));out=Path.of(args[2]);Files.createDirectories(out);try(ZipFile z=new ZipFile(original.toFile())){metadata=new String(z.getInputStream(z.getEntry("META-INF/mods.toml")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}
  var version=FMLLoader.class.getDeclaredField("versionInfo");version.setAccessible(true);version.set(null,new VersionInfo("21.1.256","4.0.45","1.21.1","20240808.144430"));var d=FMLLoader.class.getDeclaredField("dist");d.setAccessible(true);d.set(null,Dist.DEDICATED_SERVER);
  byte[] jarBefore=Files.readAllBytes(original);var p=plan(original);check(p.targets().equals(Set.of(E,I,T,C)),"exact four targets with cross-registry same ID accepted");check(p.registryKind(I)==ForgeRegistryTransformationPlan.Kind.ITEM&&p.registryKind(T)==ForgeRegistryTransformationPlan.Kind.TAB,"independent typed keys");
  for(var n:nodes().values()) {byte[] before=bytes(n);var after=p.transform(n,null);check(Arrays.equals(before,bytes(n)),"clone unchanged "+n.name);Files.write(out.resolve(n.name.substring(n.name.lastIndexOf('/')+1)+".before.class"),before);Files.write(out.resolve(n.name.substring(n.name.lastIndexOf('/')+1)+".after.class"),bytes(after));
   if(n.name.equals(T)){String tab="L"+ForgeRegistryTransformationPlan.TAB+";";check(after.fields.stream().anyMatch(f->f.name.equals("DECLARATIONS")&&f.signature.equals("L"+ForgeRegistryTransformationPlan.N+"DeferredRegister<"+tab+">;")),"Tab register generic preserved");check(after.fields.stream().anyMatch(f->f.name.equals("SHELF")&&f.signature.equals("L"+ForgeRegistryTransformationPlan.N+"DeferredHolder<"+tab+tab+">;")),"Tab Holder dual generic exact");}
   if(n.name.equals(C)){String tab="L"+ForgeRegistryTransformationPlan.TAB+";";check(method(after,"tabReceipt").signature.equals("()L"+ForgeRegistryTransformationPlan.N+"DeferredHolder<"+tab+tab+">;"),"cross-class Tab return dual generic exact");}
   for(MethodNode m:n.methods)if((m.access&Opcodes.ACC_PRIVATE)!=0&&(m.access&Opcodes.ACC_STATIC)!=0){MethodNode actual=after.methods.stream().filter(a->a.name.equals(m.name)).findFirst().orElseThrow();MethodNode expected=new MethodNode();m.accept(expected);for(var op:expected.instructions){if(op instanceof FieldInsnNode f&&f.desc.equals(H))f.desc="L"+ForgeRegistryTransformationPlan.N+"DeferredHolder;";if(op instanceof MethodInsnNode c){if(c.owner.equals(F+"RegistryObject"))c.owner=ForgeRegistryTransformationPlan.N+"DeferredHolder";if(c.desc.equals("()"+H))c.desc="()L"+ForgeRegistryTransformationPlan.N+"DeferredHolder;";}}check(text(expected).equals(text(actual)),"business change limited to typed Holder ABI "+n.name+"."+m.name);}
  }
  reject("wrong-tab-key",T,n->{for(var op:method(n,"<clinit>").instructions)if(op instanceof FieldInsnNode f&&f.name.equals("CREATIVE_MODE_TAB"))f.name="BLOCK";},"WRONG_TYPED_REGISTRY_KEY");
  reject("wrong-create-descriptor",T,n->{for(var op:method(n,"<clinit>").instructions)if(op instanceof MethodInsnNode c&&c.name.equals("create"))c.desc=ForgeRegistryTransformationPlan.CREATE;},"UNKNOWN_DEFERRED_REGISTER_DESCRIPTOR");
  reject("wrong-tab-generic",T,n->n.fields.get(1).signature=ForgeRegistryTransformationPlan.Kind.ITEM.generic("RegistryObject"),"ITEM_FIELD_DESCRIPTOR");
  reject("wrong-tab-holder-desc",T,n->n.fields.get(1).desc="Ljava/lang/Object;","ITEM_FIELD_DESCRIPTOR");
  reject("bootstrap",T,n->indy(n,"make").bsm=new Handle(Opcodes.H_INVOKESTATIC,"foreign/Bootstrap","make","()V",false),"TAB_CALLBACK_BOOTSTRAP");
  reject("captured-icon",T,n->indy(n,"make").desc="(Ljava/lang/Object;)Ljava/util/function/Supplier;","TAB_CALLBACK_BOOTSTRAP");
  reject("foreign-handle",T,n->indy(n,"make").bsmArgs[1]=new Handle(Opcodes.H_INVOKESTATIC,"foreign/Icon","get","()Lnet/minecraft/world/item/ItemStack;",false),"TAB_CALLBACK_OWNERSHIP");
  reject("wrong-handle-return",T,n->indy(n,"make").bsmArgs[1]=new Handle(Opcodes.H_INVOKESTATIC,T,"icon","()Ljava/lang/Object;",false),"TAB_CALLBACK_OWNERSHIP");
  reject("wrong-callback-local",T,n->{for(var op:method(n,"display").instructions)if(op instanceof VarInsnNode v)v.var=0;},"TAB_CALLBACK_LOCAL");
  reject("eager-holder-get",T,n->method(n,"make").instructions.insert(new MethodInsnNode(Opcodes.INVOKESTATIC,C,"first","()Lnet/minecraft/world/item/Item;",false)),"UNVERIFIED_TAB_API_OR_EAGER_CONSUMER");
  reject("eager-icon-call",T,n->method(n,"<clinit>").instructions.insert(new MethodInsnNode(Opcodes.INVOKESTATIC,T,"icon","()Lnet/minecraft/world/item/ItemStack;",false)),"UNKNOWN_DEFERRED_REGISTER_DESCRIPTOR");
  reject("wrong-item-source",T,n->{for(var op:method(n,"icon").instructions)if(op instanceof FieldInsnNode f&&f.owner.equals(I)){f.owner=T;f.name="SHELF";}},"TAB_HOLDER_SOURCE");
  reject("wrong-output-call",T,n->{for(var op:method(n,"display").instructions)if(op instanceof MethodInsnNode c&&c.name.equals("accept"))c.desc="(Ljava/lang/Object;)V";},"UNVERIFIED_TAB_CALLBACK_API");
  reject("unmapped-api",T,n->method(n,"icon").instructions.insert(new MethodInsnNode(Opcodes.INVOKESTATIC,"net/minecraftforge/Unknown","call","()V",false)),"UNVERIFIED_TAB_CALLBACK_API");
  reject("callback-branch",T,n->{var m=method(n,"icon");LabelNode l=new LabelNode();m.instructions.insert(l);m.instructions.insert(new JumpInsnNode(Opcodes.GOTO,l));},"TAB_CALLBACK_INSTRUCTION");
  reject("callback-exception",T,n->{var m=method(n,"icon");LabelNode start=new LabelNode(),end=new LabelNode();m.instructions.insert(start);m.instructions.insertBefore(m.instructions.getLast(),end);m.tryCatchBlocks.add(new TryCatchBlockNode(start,end,end,"java/lang/Exception"));},"METHOD_METADATA");
  reject("callback-stack",T,n->method(n,"icon").maxStack=0,"BYTECODE_FRAME_VERIFICATION");
  reject("consumer-generic",C,n->method(n,"tabReceipt").signature="()"+ForgeRegistryTransformationPlan.Kind.ITEM.generic("RegistryObject"),"CONSUMER_RETURN");
  reject("consumer-missing-call",T,n->{for(var op:method(n,"display").instructions)if(op instanceof MethodInsnNode c&&c.owner.equals(C))c.name="missing";},"MISSING_METHOD_CLOSURE");
  reject("consumer-cast",C,n->{for(var op:method(n,"first").instructions)if(op instanceof TypeInsnNode t)t.desc=ForgeRegistryTransformationPlan.TAB;},"CONSUMER_CHECKCAST");
  reject("uninitialized-icon-alias",T,n->{var m=method(n,"icon");for(var op:m.instructions.toArray())if(op.getOpcode()==Opcodes.DUP){m.instructions.set(op,new TypeInsnNode(Opcodes.NEW,"net/minecraft/world/item/ItemStack"));break;}},"TAB_CALLBACK_ALLOCATION");
  reject("same-registry-duplicate",I,n->{for(var op:method(n,"<clinit>").instructions)if(op instanceof LdcInsnNode l&&"second".equals(l.cst))l.cst="shared";},"DUPLICATE_OR_INVALID_REGISTRY_ID");
  reject("wrong-receiver",T,n->{for(var op:method(n,"attach").instructions)if(op instanceof FieldInsnNode f)f.owner=I;},"ATTACHMENT_RECEIVER_BUS");
  reject("wrong-entry-owner",E,n->{for(var op:method(n,"<init>").instructions)if(op instanceof MethodInsnNode c&&c.owner.equals(T))c.owner="foreign/Tab";},"HELPER_OUTSIDE_MODFILE");
  // 4C-3 authorizes the old exact register(this) input; unsupported post remains rejected.
  reject("unsupported-global-bus-post",E,n->{InsnList c=new InsnList();c.add(new FieldInsnNode(Opcodes.GETSTATIC,"net/minecraftforge/common/MinecraftForge","EVENT_BUS",ForgeRegistryTransformationPlan.BUS));c.add(new VarInsnNode(Opcodes.ALOAD,0));c.add(new MethodInsnNode(Opcodes.INVOKEINTERFACE,"net/minecraftforge/eventbus/api/IEventBus","post","(Ljava/lang/Object;)V",true));method(n,"<init>").instructions.insertBefore(Arrays.stream(method(n,"<init>").instructions.toArray()).filter(op->op.getOpcode()==Opcodes.RETURN).findFirst().orElseThrow(),c);},"unverified constructor effect");
  check(Arrays.equals(jarBefore,Files.readAllBytes(original)),"frozen input unchanged");System.out.println("TYPED REGISTRY CONTRACT PASS assertions="+assertions+" negatives="+negatives);
 }
}
